"""Paths and constants."""

from pathlib import Path

# Project root (3 levels up from this file: src/dca/config.py → src/dca → src → root)
PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent

# Code-side subdirs. The operator's data (deals, scans, the batch ledger) lives
# under the DATA root, which may be elsewhere — see `dca.paths`.
TEMPLATES_DIR = PROJECT_ROOT / "templates"
DATA_DIR = PROJECT_ROOT / "data"

# Template filenames. The demo templates are generated by scripts/make_demo_templates.py.
#   agreement  — one template for both deal kinds (conditional paragraphs by deal_kind / variant)
#   annex      — rendered once per annex of the agreement
#   cover_list — numbered list of the attachment pack (outgoing deals only)
TEMPLATE_FILES = {
    "agreement":  "agreement.docx",
    "annex":      "annex.docx",
    "cover_list": "cover_list.docx",
}

# Amendment — rendered on demand by `dca amend` (annexes + this), not part of the package.
AMENDMENT_TEMPLATE = "amendment.docx"
AMENDMENT_OUTPUT = "Amendment_{num}.docx"
AMENDMENT_DIR = "amendment_{num}"  # per-deal subfolder holding the on-demand set

# Transfer act — rendered on demand by `dca transfer` (and refreshed by `dca generate`
# when the «Передача» sheet is filled) into output_<num>/transfer_docs_<num>/.
# NOT part of the package ZIP.
TRANSFER_TEMPLATE = "transfer_act.docx"
TRANSFER_OUTPUT = "TransferAct_{num}.docx"
TRANSFER_DIR = "transfer_docs_{num}"

# Transfer act layout. Each box row has an exact one-line height (Arial 8 pt), so Word
# clips instead of wrapping; the engine lays multi-line boxes out itself, one
# `transfer_<box>_line_N` variable per form row (see context.build_transfer_context).
TRANSFER_FONT_SIZE_PT = 8.0
TRANSFER_LINE_BOXES = {       # box: (label for errors, width_pt, rows)
    "sender":   ("box 1 (handed over by)", 250.0, 4),
    "receiver": ("box 2 (received by)",    250.0, 4),
    "item":     ("box 3 (item)",           160.0, 3),
    "note":     ("box 4 (note)",           250.0, 3),
}
# Single cells that must not overflow: context key → (label, width_pt, max_lines).
TRANSFER_FIELD_LIMITS = {
    "place_from_ru":        ("box 5 (place from)", 190.0, 1),
    "place_to_ru":          ("box 6 (place to)",   190.0, 1),
    "transfer_annexes_ref": ("box 7 (annexes)",    250.0, 1),
}

# Default empty Excel template (copied into new deal folders)
EMPTY_TEMPLATE = DATA_DIR / "input_template_EMPTY.xlsx"

# Per-deal file/folder naming patterns (use {num} = agreement_num)
INPUT_FILENAME = "input_{num}.xlsx"
OUTPUT_DIR = "output_{num}"
SIGNED_DIR = "signed_{num}"  # operator-managed folder for signed PDFs (never touched by pipeline)
RUN_COMMAND_FILENAME = "run_{num}.command"
TRANSFER_RUN_COMMAND_FILENAME = "transfer_{num}.command"  # double-click → dca transfer
AMENDMENT_RUN_COMMAND_FILENAME = "amend_{num}.command"   # double-click → dca amend

OUTPUT_FILES = {
    "agreement":  "Agreement_{num}.docx",
    "annex":      "Annex_{num}.docx",
    "cover_list": "CoverList_{num}.docx",
    "log":        "log.json",
    "package":    "Package_{num}.zip",
}

# Enums
CURRENCIES_SUPPORTED = ["USD", "EUR"]
UNITS_OF_MEASURE = ["kg", "pcs", "t"]
VARIANTS = ["A", "B"]
BATCH_SLOTS = 5
